"""Generate a snapshot-pinned exact-key deletion helper; makes no cloud calls."""
import pathlib,json,hashlib
P=pathlib.Path(__file__).parent;RUN=P.parent
path=P/'root-outside-gcs-owned-manifest.json';m=json.load(open(path));digest=hashlib.sha256(path.read_bytes()).hexdigest();allow={a['name']:a['ownershipProofSha256'] for a in m['allowlist']}
assert m['project']=='halo-cmm-dev' and m['session']=='01a1d445' and m['kind']=='OUTSIDE_EXACT_KEYS' and len(allow)==len(m['allowlist'])
assert all(r['ownershipVerified'] is True and r['name'] in allow and r['ownershipProofSha256']==allow[r['name']] for r in m['objects'])
s=(RUN/'prep-helpers/DeleteOwnedGcsVersions.java').read_text().replace('DeleteOwnedGcsVersions','DeleteOwnedOutsideGcsVersions').replace('Deletes only reviewed exact versions under this run\'s four private prefixes.','Deletes only reviewed exact outside object versions from this embedded allowlist.')
a=s.index('  static final List<String> PREFIXES=');b=s.index('  static void require(',a)
constants='  static final String EXPECTED_SNAPSHOT_SHA256='+json.dumps(digest)+';\n  static final String EXPECTED_ALLOWLIST_SHA256='+json.dumps(m['allowlistSha256'])+';\n  static final Map<String,String> ALLOWED=Map.ofEntries(\n'+',\n'.join('      Map.entry('+json.dumps(k)+','+json.dumps(v)+')' for k,v in sorted(allow.items()))+');\n';s=s[:a]+constants+s[b:]
s=s.replace('require(sha.equals(a[1]),"Snapshot hash mismatch");','require(sha.equals(a[1])&&sha.equals(EXPECTED_SNAPSHOT_SHA256),"Reviewed snapshot hash mismatch");')
s=s.replace('require(kind.equals("RAW_DONE_FIRST")||kind.equals("REMAINING"),"Wrong cleanup pass");','require(kind.equals("OUTSIDE_EXACT_KEYS"),"Wrong cleanup pass");\n    require(manifest.get("allowlistSha256").getAsString().equals(EXPECTED_ALLOWLIST_SHA256),"Reviewed allowlist hash mismatch");\n    Set<String> allowNames=new HashSet<>();\n    for(JsonElement el:manifest.getAsJsonArray("allowlist")){JsonObject r=el.getAsJsonObject();String n=r.get("name").getAsString();require(r.get("bucket").getAsString().equals(BUCKET)&&allowNames.add(n)&&Objects.equals(ALLOWED.get(n),r.get("ownershipProofSha256").getAsString()),"Allowlist proof mismatch");}\n    require(allowNames.equals(ALLOWED.keySet()),"Missing/extra allowlist names");')
s=s.replace('require(bucket.equals(BUCKET)&&PREFIXES.stream().anyMatch(name::startsWith)&&!name.contains("..")&&generation>0&&meta>0,"Outside reviewed private version scope");','require(bucket.equals(BUCKET)&&ALLOWED.containsKey(name)&&!name.contains("..")&&generation>0&&meta>0,"Outside embedded exact-key version scope");\n      require(row.get("ownershipVerified").getAsBoolean()&&Objects.equals(ALLOWED.get(name),row.get("ownershipProofSha256").getAsString())&&row.get("sha256").getAsString().matches("[0-9a-f]{64}"),"Missing content/ownership proof");')
a=s.index('      boolean rawDone=');b=s.index('    Map<String,Object> journal=',a);s=s[:a]+'    }\n'+s[b:]
s=s.replace('Path output=Path.of(a[3]);atomic(output,journal);','Path output=Path.of(a[3]).toAbsolutePath().normalize();\n    require(output.getParent().toRealPath().equals(Path.of("/tmp/vid-cloud-data-01a1d445").toRealPath())&&output.getFileName().toString().startsWith("root-outside-gcs-delete-journal-")&&!Files.exists(output),"Unique session journal path required");atomic(output,journal);')
s=s.replace('exact private versions','exact outside versions')
(P/'DeleteOwnedOutsideGcsVersions.java').write_text(s)
(P/'root-outside-gcs-helper-binding.json').write_text(json.dumps({'project':m['project'],'session':m['session'],'snapshotSha256':digest,'allowlistSha256':m['allowlistSha256'],'exactNames':sorted(allow),'versions':len(m['objects']),'helperSourceSha256':hashlib.sha256(s.encode()).hexdigest(),'executed':False,'requiresRefreshAfter2B':True},indent=2)+'\n')
print('Prepared exactname-pinned helper',len(allow),'keys',len(m['objects']),'versions',digest)
